import re


def to_base36(n: int, width: int = 4) -> str:
    """Convert an integer to a zero-padded base36 string of given width."""
    chars = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ'
    result = ''
    for _ in range(width):
        result = chars[n % 36] + result
        n //= 36
    return result


def from_base36(s: str) -> int:
    """Convert a base36 string to an integer."""
    return int(s, 36)


def next_id(current_id: str) -> str:
    """Given ORD-XXXX, return the next ORD-XXXX."""
    suffix = current_id.split('-')[1]
    n = from_base36(suffix)
    return 'ORD-' + to_base36(n + 1)


def main():
    with open('ids.txt') as f:
        lines = f.readlines()

    last_id = None
    for line in lines:
        line = line.strip()
        if not line:
            continue
        # Lines may be "NUMBER\tORD-XXXX" or just "ORD-XXXX"
        match = re.search(r'ORD-[0-9A-Z]{4}', line)
        if match:
            last_id = match.group()

    if last_id is None:
        print('ORD-0000')
    else:
        print(next_id(last_id))


if __name__ == '__main__':
    main()

