#!/usr/bin/env python3
"""Remove duplicate events from events.jsonl by event_id, writing to deduped.jsonl.

Duplicate events that share an event_id keep the most recent version (by
reported_at), and the remaining events are written in chronological order.
"""

import json
from datetime import datetime


def parse_ts(value):
    """Parse an ISO 8601 timestamp into a comparable datetime."""
    try:
        ts = value
        if ts.endswith("Z") or ts.endswith("z"):
            ts = ts[:-1] + "+00:00"
        return datetime.fromisoformat(ts)
    except (TypeError, ValueError):
        # Fall back to a string comparison for unparseable values.
        return value


def main():
    latest = {}

    with open("events.jsonl", encoding="utf-8") as fh:
        for line in fh:
            line = line.strip()
            if not line:
                continue
            event = json.loads(line)
            event_id = event.get("event_id")

            current = latest.get(event_id)
            if current is None or parse_ts(event.get("reported_at")) >= parse_ts(current.get("reported_at")):
                latest[event_id] = event

    remaining = sorted(latest.values(), key=lambda e: parse_ts(e.get("reported_at")))

    with open("deduped.jsonl", "w", encoding="utf-8") as fh:
        for event in remaining:
            fh.write(json.dumps(event) + "\n")


if __name__ == "__main__":
    main()
EOF
