"""Print the file names under reports/ in report order, one per line."""

import os
import re

REPORTS_DIR = "reports"

def report_sort_key(name: str) -> tuple[int, ...]:
    """Extract the numeric part of report-<n>.txt for sorting."""
    m = re.search(r"report-(\d+)\.txt", name)
    if m:
        return (int(m.group(1)),)
    return (0,)

def main() -> None:
    try:
        entries = os.listdir(REPORTS_DIR)
    except FileNotFoundError:
        return

    report_files = [e for e in entries if re.match(r"^report-\d+\.txt$", e)]
    report_files.sort(key=report_sort_key)

    for f in report_files:
        print(f)

if __name__ == "__main__":
    main()

