def parse_timestamp(line):
    """Try to parse a YYYY-MM-DD HH:MM:SS timestamp from the start of a line."""
    if len(line) < 19:
        return None
    try:
        return datetime.strptime(line[:19], "%Y-%m-%d %H:%M:%S").replace(tzinfo=timezone.utc)
    except ValueError:
        return None

def main():
    if len(sys.argv) != 2:
        print("Usage: python rotate.py AS_OF", file=sys.stderr)
        sys.exit(1)

    as_of_ts = int(sys.argv[1])
    as_of_dt = datetime.fromtimestamp(as_of_ts, tz=timezone.utc)
    cutoff_dt = as_of_dt.timestamp() - 7 * 86400
    cutoff_dt_obj = datetime.fromtimestamp(cutoff_dt, tz=timezone.utc)

    app_log_path = "app.log"
    archive_log_path = "archive.log"

    # Read all lines from app.log
    with open(app_log_path, "r") as f:
        lines = f.readlines()

    keep_lines = []
    archive_lines = []

    for line in lines:
        ts = parse_timestamp(line)
        if ts is not None and ts < cutoff_dt_obj:
            archive_lines.append(line)
